\documentclass[border=5mm]{standalone}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{calc, arrows, intersections}
\usepgfplotslibrary{fillbetween}

\begin{document}

\pagestyle{empty}

% Colors
\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\newcommand{\mydot}[2]{
    \node[circle, draw=none, fill=#2, inner sep=1.5pt] at (axis cs:#1) {};
}

\begin{tikzpicture}[declare function={f(\x)=-0.9*\x+39/4;}]

\begin{axis}[
%clip=false,
enlargelimits=false,
tick label style={font=\footnotesize},
label style={font=\small},
tick style={draw=black,thick}, minor tick style={draw=none},
axis line style = thick,
axis y line = middle, axis x line = middle,
%axis equal,
%grid = both, grid style={thin, color=lightgray!50},
xmin = 0, xmax = 10.5,
%axis x discontinuity=crunch, %crunch|parallel|none
ymin = 0, ymax = 10.5,
axis y discontinuity=crunch, %crunch|parallel|none
xtick = {0,2,...,10}, %xticklabels = {,,},
ytick = {0,2,...,10}, yticklabels = {0,20,...,100},
minor xtick={0,1,...,10},
minor ytick={0,1,...,10},   
xlabel = {Hours playing}, ylabel = {Scores},
x label style={at={(axis description cs:0.5,-0.1)},anchor=north},
y label style={at={(axis description cs:-0.1,.5)},rotate=90,anchor=south},
]

% Random seed
\pgfmathsetseed{3}

% Closer to 0 -> more linear 
\def\spread{0.6}

\def\startpoint{1}
\def\endpoint{9}
\def\offset{5}

% Lines
\plot[domain={\startpoint-\offset}:{\endpoint+\offset}, variable=\x, orangepeel, thin, dashed, name path=u]{f(\x)+1.5*\spread};
\plot[domain={\startpoint-\offset}:{\endpoint+\offset}, variable=\x, orangepeel, thin, dashed, name path=d]{f(\x)-1.5*\spread};
\plot[orangepeel!40, fill opacity=0.15] fill between [of=u and d];
\plot[domain={\startpoint-\offset}:{\endpoint+\offset}, variable=\x, orangepeel, very thick]{f(\x)};

\foreach \x [evaluate=\x as \y using f(\x)] in {1,1.15,...,9}{
	\edef\temp{
		\noexpand
		\node[circle, draw=none, fill=deepskyblue, inner sep=1.5pt] at (axis cs: \x, \y+rand*\spread) {};
	}\temp
}

\end{axis}

\end{tikzpicture}
\end{document}

